# construct exact ray rule inferred from both demos
centers=[(3,6,8,'A'),(4,13,4,'B'),(12,14,1,'C'),(14,3,2,'D')]
marks={}
for r,c,col,n in centers:
 for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]: marks[(r+dr,c+dc)]=n
orig2=[[0]*19 for _ in range(19)]
for (r,c),n in marks.items(): orig2[r][c]=3
for r,c,col,n in centers: orig2[r][c]=col
horiz={}; vert={}
for r,c,col,n in centers:
 for dr,dc,dest in [(0,-1,horiz),(0,1,horiz),(-1,0,vert),(1,0,vert)]:
  rr,cc=r+dr,c+dc
  while 0<=rr<19 and 0<=cc<19:
   if orig2[rr][cc]==3 and marks.get((rr,cc))!=n: break
   if orig2[rr][cc]!=3:
    dest[(rr,cc)]=col
   rr+=dr;cc+=dc
out2=[]
for r in range(19):
 row=[]
 for c in range(19):
  if orig2[r][c]==3: val=3
  elif (r,c) in vert: val=vert[(r,c)]
  elif (r,c) in horiz: val=horiz[(r,c)]
  else: val=0
  row.append(val)
 out2.append(row)
print(out2)
